SELECT p.id AS position_id, e.id, e.wallet_position_id, e.event_type, e.old_value_usdt, e.new_value_usdt, e.market_price_usdt, LEFT(e.reason,500) AS reason, e.occurred_at FROM paper_position p JOIN position_management_event e ON e.symbol=p.symbol AND e.occurred_at BETWEEN p.opened_at - INTERVAL 5 SECOND AND p.closed_at + INTERVAL 5 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, e.occurred_at LIMIT 200